{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Picroside-II, an iridoid glycoside closely analogous to the query's glucose-linked iridoid scaffold, rapidly penetrated the BBB and was detected in rat brain tissue after systemic administration, providing direct in vivo evidence for meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Isovitexin, a polar glycoside with multiple hydroxyl groups, was detected in rat cerebellum at 15.04 ng/mL after i.v. administration, demonstrating that glycoside-type molecules can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Thymidine, a nucleoside glycoside, is readily transported across the BBB and taken up into brain cells, supporting transporter-mediated CNS access for glycoside-like substrates.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Vidarabine, a polar nucleoside, achieved a mean CSF-to-plasma ratio of 35% in humans, showing meaningful CNS penetration for a glycoside-like molecule in the clinic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "BA10, a glycosylated natural product, showed high brain uptake and reversible tracer kinetics in pigs, providing additional in vivo evidence that glycoside-containing molecules can achieve adequate CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transferability in vivo studies on structurally related glycosides and nucleosides consistently demonstrate meaningful BBB/CNS access, including direct brain detection, CSF penetration, and transporter-mediated uptake. The query's iridoid glycoside structure is well covered by these positive experimental anchors.",
  "evidence_gaps": [
    "No direct quantitative brain-to-plasma or unbound brain concentration data are available for the exact query molecule.",
    "The specific transport mechanism for the query (passive diffusion vs. transporter-mediated uptake) is not directly established.",
    "Potential efflux liability for the query was not directly measured, though the positive in vivo glycoside evidence suggests it is not limiting."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

